SELECT blocked.pid AS blocked_pid, blocked.query AS blocked_query, blocking.pid AS blocking_pid, blocking.query AS blocking_query, blocking.state AS blocking_state, blocking.wait_event_type AS blocking_wait_type, now() - blocking.query_start AS blocking_duration FROM pg_locks bl JOIN pg_stat_activity blocked ON bl.pid = blocked.pid JOIN pg_locks kl ON kl.transactionid = bl.transactionid AND kl.granted JOIN pg_stat_activity blocking ON kl.pid = blocking.pid WHERE NOT bl.granted;
